// -------------------- LAZY DOWNLOAD ------------------

document.onload = function(){
 var div = document.querySelectorAll('.hide-section');
 const lazy = new lazyLoad(div);
 lazy.maybeLoad();
};

var isScrolling = false;
window.addEventListener('scroll', throttleScroll, false);

function throttleScroll(){
  if(isScrolling == false){
    requestAnimationFrame(function(){
      var div = document.querySelectorAll('.hide-section');
      const lazy = new lazyLoad(div);
      lazy.maybeLoad();
      isScrolling = false;
    });
  }
  isScrolling = true;
}

document.getElementById('main-slider').addEventListener("transitionend", trEnd);

function trEnd(e){
  if(e.target === this){
    const mainSlider = document.getElementById('main-slider');
    const slides = Array.from(mainSlider.querySelectorAll('.slide'));
    const id = '#'+mainSlider.getAttribute('id');
    let slider = new Slider(slides, id+' .slide.playing', mainSlider.querySelector('.slide-nav'), 
                            id+' .slide-btn', 'fade', 7000);
    slider.getPos();
    slider.playLoop();
    slider.setNav();
    slider.currNavBtn();
    slider.processNav();
    slider.setArrows();
    slider.getArrows();
    document.querySelector('#main-slider .slide-2').addEventListener("animationstart", anStart);
    this.removeEventListener("transitionend", trEnd);
  }
}

function anStart(e){
  if(e.target === this && e.target.classList.contains('playing')){
    document.querySelector('.cls-2').classList.add('draw-graph');
    this.removeEventListener("animationstart", anStart);
  }
}

//---------------- CONTACT FORM ------------------//

const contactForm = document.getElementById('home-form');
const contactInputs = document.querySelectorAll('#home-form .get-value');
const contactBtn = document.getElementById('register-btn');

contactForm.addEventListener('submit', async event => {
  let isNotEmpty = true;
  event.preventDefault();
  contactInputs.forEach(field => {
    if(field.value.length === 0){
      field.style.border = '1px solid red';
      isNotEmpty = false;
    }
  });

  if(isNotEmpty){
    //grecaptcha.execute();
    formSubmit();
  }else{
    //grecaptcha.reset();
  }
});

async function formSubmit(){
  const note = document.getElementById('form-note');
  const url = '/support/process-request';
  contactBtn.disabled = true;
  contactBtn.value = 'Please Wait';
  if(document.getElementById('form-error')) document.getElementById('form-error').remove();
  var errorBox = document.createElement('p');
  errorBox.setAttribute('id', 'form-error');
  const formData = new FormData(contactForm);
  try {
    const response = await fetch(url, {
      method: 'post',
      body: formData
    });
    const result = await response.text();
    if(result == 0){
      const txt = document.createTextNode('Something went wrong. Please try again.');
      errorBox.appendChild(txt);
      note.append(errorBox);
      contactBtn.disabled = false;
      contactBtn.value = 'Submit';
      //grecaptcha.reset();
    }else if(result == 2){
      const txt = document.createTextNode('Please provide valid email address.');
      errorBox.appendChild(txt);
      note.append(errorBox);
      contactBtn.disabled = false;
      contactBtn.value = 'Submit';
      //grecaptcha.reset();
    }else if(result == 3){
      const txt = document.createTextNode("The reCAPTCHA wasn't entered correctly. Please try again.");
      errorBox.appendChild(txt);
      note.append(errorBox);
      contactBtn.disabled = false;
      contactBtn.value = 'Submit';
      //grecaptcha.reset();
    }else if(result == 4){
      const txt = document.createTextNode("Generic email domains(i.e. gmail, yahoo, hotmail) are not accepted.");
      errorBox.appendChild(txt);
      note.append(errorBox);
      contactBtn.disabled = false;
      contactBtn.value = 'Submit';
      //grecaptcha.reset();
    }else{
      location.href = '/support/thank-you';
    }
  } catch (error) {
     console.log(error);
  }
}

//----------- PROCESS MOBILE DIRECTIONAL DIAGRAM ARROWS ---------//
let pos = 0;
var winW = window.innerWidth;
if(winW < 515){
  pos = 780 - winW;
}else{
  pos = 880 - winW;
}

document.querySelectorAll('.diagram-mobile-nav li').forEach(dnav => {
  dnav.addEventListener('click', function(e){
    e.preventDefault();
    var diagram = document.getElementById(this.parentElement.getAttribute('data-fig'));
    diagram.style.transform = 'translateX(0)';
    if(this.classList.contains('slide-left')){
      animate(diagram, '+', pos);
    }
    if(this.classList.contains('slide-right')){
      animate(diagram, '-', pos);
    }
  });
});


function animate(elem, dir, limit){
  var cnt = 0;
  function frame(){
      cnt++;
      if(dir=='+') elem.style.transform = 'translateX(0)';
      if(dir=='-') elem.style.transform = 'translateX('+dir+cnt + 'px)';
      if(cnt == limit) clearInterval(timer);
  }
  var timer = setInterval(frame, 10);
}
</script>
</body>
